import { createSlotSymbolCatalog, type SlotGameDefinition, type SlotSymbolDefinition } from '../models/SlotGameTypes';

// 照 games/chinhoyiah.json 後端球的面值
const MULTIPLIER_VALUES = [2, 3, 4, 5, 6, 8, 10, 12, 15, 20, 25, 50, 100, 250, 500, 1000] as const;

// 球的顏色階 1 最高 4 最低
const colorTierOf = (value: number): number => (value <= 8 ? 4 : value <= 25 ? 3 : value <= 80 ? 2 : 1);

const NORMAL_SYMBOLS = [
    { id: 1, kind: 'normal', name: 'sym1', frame: 'symbol_h1' },
    { id: 2, kind: 'normal', name: 'sym2', frame: 'symbol_h2' },
    { id: 3, kind: 'normal', name: 'sym3', frame: 'symbol_h3' },
    { id: 4, kind: 'normal', name: 'sym4', frame: 'symbol_h4' },
    { id: 5, kind: 'normal', name: 'sym5', frame: 'symbol_l1' },
    { id: 6, kind: 'normal', name: 'sym6', frame: 'symbol_l2' },
    { id: 7, kind: 'normal', name: 'sym7', frame: 'symbol_l3' },
    { id: 8, kind: 'normal', name: 'sym8', frame: 'symbol_l4' },
    { id: 9, kind: 'normal', name: 'sym9', frame: 'symbol_l5' },
] satisfies readonly SlotSymbolDefinition[];

const SCATTER_SYMBOL = { id: 10, kind: 'scatter', name: 'scatter', frame: 'symbol_scatter' } satisfies SlotSymbolDefinition;

const multiplierSymbols = (startId: number): SlotSymbolDefinition[] =>
    MULTIPLIER_VALUES.map((value, index) => ({
        id: startId + index,
        kind: 'multiplier',
        name: `mul${value}`,
        value,
        upgradeable: false,
        colorTier: colorTierOf(value),
        frame: ({ symbol }) => `symbol_m1_${symbol.colorTier}`,
    }));

/** 這支 bundle 對應的玩家端 API `game_id` */
export const API_GAME_ID = 'chinhoyiah';

export const SLOT_GAME_DEFINITION: SlotGameDefinition = {
    symbols: createSlotSymbolCatalog({
        symbols: [
            ...NORMAL_SYMBOLS,
            SCATTER_SYMBOL,
            ...multiplierSymbols(11),
        ],
        fallback: { kind: 'normal', name: 'unknown', frame: 'symbol_h1' },
    }),
};

// 倍率球的 id 起點 一個面值一個 id 依 MULTIPLIER_VALUES 順序
const MULTIPLIER_ID_BASE = 11;

// 後端的球只有一個符號 id 面值放在格子標記
export const BOOM_SYMBOL_ID = 11;

/**
 * 給演出邏輯共用的 ID 常數。
 *
 * @see SYMBOL_IDS.multiplierPool 為什麼倍率球只有一個池 id。
 */
export const SYMBOL_IDS = {
    normalMin: 1,
    normalMax: NORMAL_SYMBOLS.length,
    scatter: SCATTER_SYMBOL.id,
    /**
     * 所有倍率球在物件池裡共用的 id。
     *
     * 全部倍率球 id 共用同一支 `symbol_m` spine，長相差異全靠執行期設的 skin `m1_{tier}`
     * ——一個顏色階對應多種倍率值，所以「一個 id 一支 prefab」對倍率球不成立。池只認這一個 id，
     * 真正的長相由 `SymbolCell` 保存的 `SymbolExtras` 在租借後回填。
     */
    multiplierPool: MULTIPLIER_ID_BASE,
} as const;

/**
 * 這個 id 是不是倍率球。
 *
 * 用 id 範圍判斷而不是 `symbols.resolve(id).kind`，是為了讓建池與換圖這條每格都會走到的路徑
 * 不必每次去查表建物件。
 *
 * @param id 符號 id。
 * @returns 是倍率球時為 true。
 */
export function isMultiplierSymbolId(id: number): boolean {
    return id >= MULTIPLIER_ID_BASE && id < MULTIPLIER_ID_BASE + MULTIPLIER_VALUES.length;
}

/**
 * 全部倍率球的 id。
 *
 * 給「圖名 → 符號 id」的反查表用：圖名由 `symbols.frameName(id)` 產生，反查只能靠正著走一遍
 * 所有 id。列在這裡而不是在 View 裡自己組字串，命名規則才只有這個檔案知道。
 */
export const MULTIPLIER_SYMBOL_IDS: readonly number[] = MULTIPLIER_VALUES.map((_, index) => MULTIPLIER_ID_BASE + index);

/**
 * 球的面值換成倍率球的符號 id。
 *
 * @param value 後端格子標記的面值。
 * @returns 倍率球的符號 id；不是已登記的面值時 undefined。
 */
export function multiplierSymbolIdOf(value: number): number | undefined {
    const index = (MULTIPLIER_VALUES as readonly number[]).indexOf(value);
    return index < 0 ? undefined : MULTIPLIER_ID_BASE + index;
}
