// 每款遊戲的假資料玩法引擎介面
// slot-api-mock.ts 只負責傳輸與帳務 盤面與中獎規則由引擎產出 金額一律是底注倍數

import type { SlotApiBoard } from '../SlotApiTypes';

// 引擎產出的一張盤面與這張盤面實付的贏分
export interface MockBoard {
    board: SlotApiBoard;
    // 實付贏分 單位是底注的百分之一 整數
    paidCents: number;
}

// 一轉 初盤加上它的所有連消盤面 最後一張是終盤
export interface MockSpin {
    boards: MockBoard[];
    // 這一轉授的免費遊戲轉數 放在終盤那一步
    awarded: number;
}

// 一整局 第一轉是主遊戲 其餘依序是免費遊戲各轉
export interface MockRound {
    spins: MockSpin[];
}

export interface MockRoundOptions {
    // 買入免費遊戲
    buy?: boolean;
    // 加注
    extra?: boolean;
}

export interface MockRoundEngine {
    readonly gameId: string;
    readonly resultVersion: number;
    // entry 的 bb
    readonly baseBet: number;
    readonly rtp: string;
    // 單局上限 底注倍數
    readonly maxWinMultiple: number;
    // 買入檔位 entry 的 buy
    readonly buyOptions: readonly { id: string; m: string }[];
    // 加注檔位 entry 的 xb
    readonly extraOptions: readonly { id: string; m: string }[];
    // 沒玩過時 entry 的 ls.r 要畫的盤面
    makeDefaultBoard(): SlotApiBoard;
    makeRound(options?: MockRoundOptions): MockRound;
}
