import type { Component, Constructor, Node } from 'cc';
import { ORIENTATION } from '../../store/StoreMap';
import StoreManager from '../../store/StoreManager';

type HistoryViewContext = {
    addHistoryItem(orientation: ORIENTATION): Node;
};

type HistoryItemComponent = Component & {
    titleData: unknown;
    historyView: HistoryViewContext;
};

type HistoryAdapterConstructor = new () => {
    getRoundDetail(data: unknown, isPortrait: boolean): Promise<Node>;
};

export default class HistoryModel {
    view: HistoryViewContext;
    storeManager: StoreManager;
    infoData: null;
    constructor(
        context: HistoryViewContext,
        private readonly GameAdapter: HistoryAdapterConstructor,
        private readonly HistoryItem: Constructor<HistoryItemComponent>,
    ) {
        this.view = context;
        this.storeManager = StoreManager.getInstance();
    }
    async addHistoryItem() {
        const historyPage = this.storeManager.getGameStore().historyData;
        const items = historyPage?.items ?? [];
        if (items.length === 0) return;
        items.forEach((history) => {
            if (this.storeManager.getGameStore().roundId === history.operationId) return;
            const orientation = (this.storeManager.getDeviceStore().orientation || ORIENTATION.LANDSCAPE) as ORIENTATION;
            let item = this.view.addHistoryItem(orientation);
            let itemTS = item.getComponent(this.HistoryItem);
            itemTS.titleData = history;
            itemTS.historyView = this.view;
        });
    }

    async createHistoryDetailView(operationId: string): Promise<Node | null> {
        const data = await this.storeManager.getHttpClientStore()?.getHistoryDetail?.(operationId);
        if (!data) return null;

        const gameAdapter = new this.GameAdapter();
        const isPortrait = this.storeManager.getDeviceStore().orientation !== ORIENTATION.LANDSCAPE;
        return gameAdapter.getRoundDetail(data, isPortrait);
    }

}
