import type { SpinSkipController } from './SpinSkipController';

export interface SkipSource {
    readonly spinSkip: SpinSkipController;
    scheduleOnce(callback: () => void, delay: number): void;
}

/** 等工作完成或被跳過 被跳過回傳 true */
export function raceSkip(game: SkipSource, work: Promise<unknown>): Promise<boolean> {
    if (game.spinSkip.isSkipped) return Promise.resolve(true);
    return new Promise<boolean>((resolve) => {
        const off = game.spinSkip.subscribe(() => {
            off();
            resolve(true);
        });
        const done = (): void => {
            off();
            resolve(false);
        };
        work.then(done, done);
    });
}

/** 可被跳過的等待秒數 被跳過回傳 true */
export function skipWait(game: SkipSource, seconds: number): Promise<boolean> {
    return raceSkip(game, new Promise<void>((resolve) => game.scheduleOnce(resolve, seconds)));
}
